window.ANSWER_TERMS = {"ATP":{"match":"adenosinetrifosfaat|adenosine trifosfaat|adenosine-trifosfaat|ATP","title":"ATP (adenosinetrifosfaat)","short":"ATP is de energiemunt van de cel: bij afsplitsing van de derde fosfaatgroep komt energie vrij die transport, contractie en biosynthese aandrijft.","definition":"<p><strong>ATP</strong> (adenosinetrifosfaat) bestaat uit adenine, ribose en drie fosfaatgroepen. Hydrolyse van de eindstandige fosfaatbinding (ATP → ADP + P<sub>i</sub>) levert ongeveer 30 kJ/mol — genoeg om ongunstige reacties te koppelen aan een gunstige: spiercontractie, de Na⁺/K⁺-ATPase, en de opbouw van eiwitten, vetten en DNA.</p><p>Het meeste ATP komt uit de <em>oxidatieve fosforylering</em> in het mitochondrion: de elektronentransportketen pompt protonen naar de intermembraanruimte, en ATP-synthase laat die protonengradiënt terugstromen en maakt daarmee ATP (chemiosmose). Glycolyse en de citroenzuurcyclus leveren daarnaast rechtstreeks een kleine hoeveelheid.</p><p>De cel slaat ATP nauwelijks op — de voorraad gaat in seconden — dus productie en verbruik zijn strak gekoppeld: veel ADP versnelt de verbranding, overmaat ATP remt die af.</p>","image_url":"","wiki_titles":["Adenosine triphosphate","ATP synthase"]},"cholesterol":{"title":"Cholesterol","short":"Vetachtige stof die de celmembraan stevigheid en de juiste vloeibaarheid geeft en grondstof is voor steroïden.","definition":"<p><b>Cholesterol</b> is een steroïd dat tussen de fosfolipiden van de celmembraan zit en de membraanvloeibaarheid stabiliseert.</p><p>Het is bovendien de grondstof voor steroïdhormonen, vitamine D en galzouten.</p>","image_url":"","wiki_title":"Cholesterol","match":"cholesterol"},"necrose":{"title":"Necrose","short":"Ongecontroleerde celdood door schade, waarbij de cel opzwelt, openbarst en een ontstekingsreactie uitlokt.","definition":"<p><b>Necrose</b> is celdood door acute schade (zuurstoftekort, toxinen, trauma). De cel zwelt op en de membraan scheurt.</p><p>De vrijkomende celinhoud lokt een ontstekingsreactie uit — anders dan bij de 'nette' apoptose.</p>","image_url":"","wiki_title":"Necrosis","match":"necrose"},"glycolyse":{"title":"Glycolyse","short":"Afbraak van glucose tot pyruvaat in het cytoplasma, met een kleine netto-opbrengst aan ATP en NADH.","definition":"<p><b>Glycolyse</b> splitst in het cytoplasma één glucose in tien stappen tot twee moleculen pyruvaat.</p><p>Het levert netto 2 ATP en 2 NADH op en verloopt zonder zuurstof. Bij aanwezigheid van zuurstof gaat pyruvaat de citroenzuurcyclus in.</p>","image_url":"","wiki_title":"Glycolysis","match":"glycolyse"},"Langerhanscel":{"title":"Langerhanscel","short":"Dendritische immuuncel in de epidermis die antigenen opvangt en aan T-cellen presenteert.","definition":"<p>De <b>Langerhanscel</b> is een dendritische cel, vooral in het stratum spinosum. Hij vangt binnendringende antigenen op.</p><p>Vervolgens migreert hij naar de lymfeklier en presenteert het antigeen aan T-lymfocyten — de schakel tussen huid en afweer.</p>","image_url":"","wiki_title":"Langerhans cell","match":"langerhanscel|langerhanscellen|langerhans cel|langerhans cellen|cellen van langerhans"},"fibroblast":{"title":"Fibroblast","short":"De belangrijkste bindweefselcel; produceert collageen, elastine en de overige extracellulaire matrix.","definition":"<p>De <b>fibroblast</b> is de meest voorkomende cel in bindweefsel en de dermis. Hij maakt de vezels (collageen, elastine) en de grondsubstantie aan.</p><p>Bij wondgenezing migreren fibroblasten naar de wond, vormen nieuw matrixmateriaal en kunnen als myofibroblast de wond samentrekken.</p>","image_url":"","wiki_title":"Fibroblast","match":"fibroblast|fibroblasten"},"eosinofiele granulocyt":{"title":"Eosinofiele granulocyt","short":"Witte bloedcel met rood-kleurende korrels, actief bij afweer tegen parasieten en bij allergie.","definition":"<p>De <b>eosinofiele granulocyt</b> heeft korrels die met eosine roodroze aankleuren en meestal een tweelobbige kern.</p><p>Hij is betrokken bij de afweer tegen wormparasieten en bij allergische processen zoals astma en eczeem; het aantal is dan vaak verhoogd.</p>","image_url":"","wiki_title":"Eosinophil","match":"eosinofiele granulocyt|eosinofiele granulocyten"},"macrofaag":{"title":"Macrofaag","short":"Grote fagocyt in de weefsels die pathogenen en celresten opruimt en antigenen presenteert.","definition":"<p>De <b>macrofaag</b> ontstaat uit een monocyt die het weefsel is binnengegaan. Hij fagocyteert bacteriën, dode cellen en afval.</p><p>Als antigeenpresenterende cel activeert hij ook T-cellen en scheidt hij ontstekingsmediatoren uit. In de huid heten verwante cellen histiocyten.</p>","image_url":"","wiki_title":"Macrophage","match":"macrofaag|macrofagen"},"lymfeklier":{"title":"Lymfeklier","short":"Filterstation in de lymfebaan waar antigenen worden gepresenteerd en de afweerreactie op gang komt.","definition":"<p>De <b>lymfeklier</b> filtert de lymfe en is een ontmoetingsplaats voor antigeenpresenterende cellen en lymfocyten.</p><p>Hier worden T- en B-cellen geactiveerd; bij infectie zwellen lymfeklieren op doordat de lymfocyten zich vermenigvuldigen.</p>","image_url":"","wiki_title":"Lymph node","match":"lymfeklier|lymfeklieren|lymfklier|lymfklieren"},"nodulus":{"title":"Nodulus","short":"Vaste, verheven en voelbare knobbel die dieper in de huid reikt dan een papel (> ~1 cm).","definition":"<p>Een <b>nodulus</b> (nodus, knobbel) is een stevige, verheven laesie die groter is dan een papel en dieper in de dermis of subcutis reikt.</p><p>Voorbeelden zijn een dermatofibroom of sommige huidtumoren.</p>","image_url":"","wiki_title":"Nodule (medicine)","match":"nodulus|nodus|noduli|nodi"},"autosomaal dominant":{"title":"Autosomaal dominant","short":"Overervingspatroon waarbij één afwijkend gen (op een niet-geslachtschromosoom) al ziekte geeft.","definition":"<p>Bij <b>autosomaal dominante</b> overerving volstaat één gemuteerd allel op een autosoom om de aandoening tot uiting te laten komen.</p><p>Aangedane ouders geven het gemiddeld aan de helft van hun kinderen door; de aandoening komt in elke generatie voor, ongeacht geslacht.</p>","image_url":"","wiki_title":"Dominance (genetics)","match":"autosomaal dominant"},"klebsiella pneumoniae":{"title":"Klebsiella pneumoniae","short":"K. pneumoniae is een gramnegatieve staaf met een dik kapsel die urineweginfecties en (ziekenhuis)pneumonie veroorzaakt.","definition":"<p><strong><em>Klebsiella pneumoniae</em></strong> is een gramnegatieve staaf uit de <em>Enterobacteriaceae</em> met een dik polysacharidekapsel, waardoor kolonies slijmerig zijn.</p><p>Hij veroorzaakt urineweginfecties, sepsis en pneumonie, vooral bij ouderen, alcoholisten en patiënten met diabetes of in het ziekenhuis. Klebsiella is berucht om antibioticaresistentie (ESBL- en carbapenemaseproducerende stammen).</p>","image_url":"","wiki_title":"Klebsiella pneumoniae","match":"klebsiella pneumoniae|k. pneumoniae|klebsiella","option_only":true},"tuberculose":{"title":"Tuberculose","short":"Tuberculose is een infectie met Mycobacterium tuberculosis, meestal in de longen, met langdurig hoesten, nachtzweten, gewichtsverlies en granulomen.","definition":"<p><strong>Tuberculose</strong> wordt veroorzaakt door <em>Mycobacterium tuberculosis</em> en verspreidt zich via aerosolen. Na infectie wordt de bacterie meestal ingekapseld in granulomen (latente tbc); bij verminderde afweer kan actieve ziekte ontstaan.</p><p>Longtuberculose geeft langdurig hoesten (soms met bloed), koorts, nachtzweten en gewichtsverlies; typisch zijn holtevorming in de longtoppen en granulomen met centrale <em>verkazing</em>. Behandeling met een combinatie van tuberculostatica gedurende minstens 6 maanden.</p>","image_url":"","wiki_title":"Tuberculosis","match":"tuberculose|tbc|tb","option_only":true},"amoxicilline":{"title":"Amoxicilline","short":"Amoxicilline is een breedspectrum-penicilline die ook een deel van de gramnegatieve bacteriën dekt; veel gebruikt bij luchtweginfecties.","definition":"<p><strong>Amoxicilline</strong> is een aminopenicilline: een bètalactamantibioticum dat de celwandsynthese remt. Het spectrum is breder dan penicilline en omvat ook o.a. <em>H. influenzae</em> en <em>E. coli</em> (mits geen bètalactamase).</p><p>Het is in de huisartsenpraktijk eerste keus bij pneumonie en wordt ook gebruikt bij otitis en sinusitis. Met clavulaanzuur (amoxicilline-clavulaanzuur) is het ook werkzaam tegen bètalactamasevormers.</p>","image_url":"","wiki_title":"Amoxicillin","match":"amoxicilline|amoxicillin","option_only":true},"doxycycline":{"title":"Doxycycline","short":"Doxycycline is een tetracycline: een bacteriostatisch antibioticum dat de eiwitsynthese remt via het 30S-ribosoom.","definition":"<p><strong>Doxycycline</strong> behoort tot de <em>tetracyclines</em>. Het bindt aan de 30S-subeenheid van het bacteriële ribosoom en remt zo de eiwitsynthese (bacteriostatisch).</p><p>Het is werkzaam tegen veel luchtwegpathogenen en tegen intracellulaire verwekkers zoals <em>Chlamydia</em>, <em>Mycoplasma</em>, <em>Rickettsia</em> en <em>Borrelia</em> (ziekte van Lyme). Niet geven aan zwangeren en jonge kinderen (verkleuring van tanden en botten); kan fotosensibiliteit geven.</p>","image_url":"","wiki_title":"Doxycycline","match":"doxycycline","option_only":true},"prednison":{"title":"Prednison / prednisolon","short":"Prednison(olon) is een synthetisch glucocorticoïd met sterke ontstekingsremmende en immunosuppressieve werking.","definition":"<p><strong>Prednison</strong> is een prodrug die in de lever wordt omgezet in het actieve <strong>prednisolon</strong>. Beide zijn synthetische <em>glucocorticoïden</em>: ze binden aan de intracellulaire glucocorticoïdreceptor en veranderen de gentranscriptie.</p><p>Daardoor remmen ze de vorming van allerlei ontstekingsmediatoren en de activatie van ontstekingscellen. Gebruikt bij astma/COPD-exacerbaties, auto-immuunziekten en allergieën. Bijwerkingen bij langdurig gebruik: osteoporose, hyperglykemie, gewichtstoename, huidatrofie, infectierisico en bijnierschorsremming.</p>","image_url":"","wiki_title":"Prednisolone","match":"prednison|prednisolon|prednisone|prednisolone","option_only":true},"alcohol":{"title":"Alcohol (ethanol)","short":"Ethanol wordt in de lever afgebroken via acetaldehyde tot azijnzuur; overmatig gebruik schaadt lever, brein, hart en pancreas.","definition":"<p><strong>Ethanol</strong> wordt vooral in de lever geoxideerd door <em>alcoholdehydrogenase</em> tot acetaldehyde en daarna door aldehydedehydrogenase tot acetaat. Hierbij ontstaat veel NADH, wat de gluconeogenese remt (hypoglykemie) en vetstapeling in de lever bevordert.</p><p>Chronisch overmatig gebruik geeft leververvetting, alcoholische hepatitis en cirrose, pancreatitis, cardiomyopathie, hypertensie, neuropathie, thiaminetekort (Wernicke-Korsakov) en een verhoogd risico op verschillende kankers.</p>","image_url":"","wiki_title":"Alcohol (drug)","match":"alcohol|ethanol|alcoholgebruik|overmatig alcoholgebruik|alcoholmisbruik","option_only":true},"roken":{"title":"Roken","short":"Roken is de belangrijkste vermijdbare oorzaak van ziekte en sterfte: het veroorzaakt o.a. longkanker, COPD en hart- en vaatziekten.","definition":"<p>Tabaksrook bevat nicotine (verslavend), koolmonoxide, teer en tientallen kankerverwekkende stoffen. <strong>Roken</strong> beschadigt het luchtwegepitheel en het endotheel en bevordert ontsteking en trombose.</p><p>Het is een hoofdoorzaak van longkanker en andere kankers (o.a. mond, slokdarm, blaas), COPD, atherosclerose (myocardinfarct, CVA, perifeer arterieel vaatlijden) en complicaties in de zwangerschap. Stoppen loont op elke leeftijd.</p>","image_url":"","wiki_title":"Tobacco smoking","match":"roken|tabaksgebruik|tabak","option_only":true},"pneumothorax":{"title":"Pneumothorax","short":"Een pneumothorax is lucht in de pleuraholte, waardoor de long (deels) inklapt; acuut kortademig met pijn, bij spanningspneumothorax levensbedreigend.","definition":"<p>Bij een <strong>pneumothorax</strong> komt lucht tussen de pleurabladen, waardoor de negatieve intrapleurale druk verdwijnt en de long door zijn elastische terugslag inklapt.</p><p>Hij kan spontaan ontstaan (primair bij lange, slanke jonge mannen door blebs; secundair bij longziekte zoals COPD) of na trauma. Klachten: plotselinge pijn op de borst en kortademigheid; verminderd ademgeruis en hypersonore percussie. Bij een <em>spanningspneumothorax</em> hoopt lucht zich op als een ventiel, met verschuiving van het mediastinum en circulatoire shock: direct ontlasten.</p>","image_url":"","wiki_title":"Pneumothorax","match":"pneumothorax|klaplong","option_only":true},"longfibrose":{"title":"Longfibrose","short":"Bij longfibrose wordt het longinterstitium vervangen door bindweefsel; de long wordt stug, met een restrictief beeld en verminderde diffusie.","definition":"<p>Bij <strong>longfibrose</strong> leidt beschadiging en abnormaal herstel van het longinterstitium tot verlittekening. Oorzaken zijn idiopathisch (IPF), stofblootstelling (asbest, silica), auto-immuunziekten, medicatie, bestraling of chronische extrinsieke allergische alveolitis.</p><p>De long wordt stijver (lagere compliantie): een <em>restrictieve</em> longfunctiestoornis (lage TLC en VC, normale of verhoogde FEV1/FVC) met verlaagde diffusiecapaciteit. Klachten: progressieve kortademigheid en droge hoest; bij auscultatie fijne ‘knisper’crepitaties; vaak trommelstokvingers.</p>","image_url":"","wiki_title":"Pulmonary fibrosis","match":"longfibrose|pulmonale fibrose|idiopathische pulmonale fibrose|ipf","option_only":true},"hypersensitivity pneumonitis":{"title":"Extrinsieke allergische alveolitis","short":"Extrinsieke allergische alveolitis is een immuunreactie (type III/IV) in de alveoli op ingeademde organische stoffen, zoals schimmelsporen of vogeleiwitten.","definition":"<p>Bij <strong>hypersensitivity pneumonitis</strong> (extrinsieke allergische alveolitis) reageert het immuunsysteem op herhaald ingeademde organische antigenen: schimmelsporen uit hooi (boerenlong), vogeleiwitten (duivenmelkerslong) of bevochtigerwater.</p><p>Het mechanisme is een type III- (immuuncomplex) en type IV- (T-cel) reactie met lymfocytaire alveolitis en kleine granulomen. Acuut: koorts, hoesten en kortademigheid enkele uren na blootstelling; chronisch kan longfibrose ontstaan. Behandeling: blootstelling vermijden, eventueel corticosteroïden.</p>","image_url":"","wiki_title":"Hypersensitivity pneumonitis","match":"hypersensitivity pneumonitis|extrinsieke allergische alveolitis|eaa|boerenlong|vogelhoudersziekte","option_only":true},"x-thorax":{"title":"X-thorax","short":"Een X-thorax is een röntgenfoto van de borstkas; het eerste beeldvormend onderzoek bij verdenking op longafwijkingen, hartfalen of pneumothorax.","definition":"<p>Een <strong>X-thorax</strong> is een röntgenopname van de borstkas, meestal posterieur-anterieur en lateraal. Lucht is zwart, weke delen grijs en bot wit.</p><p>Het is snel, goedkoop en met een lage stralingsdosis, en wordt gebruikt om o.a. pneumonie (infiltraat), pleuravocht, pneumothorax, longtumoren, hartvergroting en tekenen van hartfalen op te sporen. Kleine of subtiele afwijkingen zijn er minder goed op te zien dan op een CT.</p>","image_url":"","wiki_title":"Chest radiograph","match":"x-thorax|thoraxfoto|röntgenfoto van de thorax|x thorax|x-thorax (röntgenfoto)","option_only":true},"hypertensie":{"title":"Hypertensie","short":"Hypertensie is een blijvend verhoogde bloeddruk (≥140/90 mmHg op het spreekuur); een belangrijke risicofactor voor hart- en vaatziekten.","definition":"<p>Bij <strong>hypertensie</strong> is de bloeddruk herhaaldelijk verhoogd: op het spreekuur ≥140/90 mmHg. Meestal is er geen aanwijsbare oorzaak (<em>primaire/essentiële</em> hypertensie); bij een minderheid is er een secundaire oorzaak, zoals nierziekte, nierarteriestenose, hyperaldosteronisme of feochromocytoom.</p><p>Hypertensie geeft meestal geen klachten, maar beschadigt op termijn vaten en organen: linkerventrikelhypertrofie, hartfalen, CVA, nierschade en retinopathie. Behandeling: leefstijl (zout, gewicht, beweging, alcohol) en medicatie (o.a. diuretica, ACE-remmers/ARB's, calciumantagonisten).</p>","image_url":"","wiki_title":"Hypertension","match":"hypertensie|hoge bloeddruk|arteriële hypertensie","option_only":true},"myocardinfarct":{"title":"Myocardinfarct","short":"Bij een myocardinfarct sterft hartspierweefsel af doordat een kransslagader (meestal door een trombus op een gescheurde plaque) afsluit.","definition":"<p>Een <strong>myocardinfarct</strong> ontstaat meestal doordat een atherosclerotische plaque in een coronairarterie scheurt, waarna een trombus het vat (deels) afsluit. Het hartspierweefsel achter de afsluiting raakt ischemisch en gaat na 20–30 minuten necrotisch.</p><p>Klachten: drukkende pijn op de borst, uitstralend naar arm, kaak of rug, met zweten, misselijkheid en benauwdheid. Diagnose op basis van klachten, ECG (ST-elevatie of niet) en een stijging van troponine. Complicaties zijn ritmestoornissen, hartfalen en mechanische complicaties. Snelle reperfusie (PCI) is cruciaal.</p>","image_url":"","wiki_title":"Myocardial infarction","match":"myocardinfarct|hartinfarct|acuut myocardinfarct|ami","option_only":true},"respiratoire alkalose":{"title":"Respiratoire alkalose","short":"Bij een respiratoire alkalose stijgt de pH doordat door hyperventilatie te veel CO₂ wordt uitgeademd (lage pCO₂).","definition":"<p>Bij een <strong>respiratoire alkalose</strong> is de pCO<sub>2</sub> verlaagd door <em>hyperventilatie</em>, waardoor de pH stijgt. Oorzaken: angst/paniek, pijn, hypoxie (hoogte, longembolie, pneumonie), koorts, zwangerschap, salicylaatintoxicatie en levercirrose.</p><p>De nier compenseert (langzaam, over dagen) door minder bicarbonaat terug te resorberen. Acute klachten: tintelingen rond de mond en in de vingers, duizeligheid en soms tetanie, door daling van het geïoniseerde calcium.</p>","image_url":"","wiki_title":"Respiratory alkalosis","match":"respiratoire alkalose","option_only":true},"metabole alkalose":{"title":"Metabole alkalose","short":"Bij een metabole alkalose is het bicarbonaat verhoogd en de pH gestegen, bijv. door braken (verlies van maagzuur) of diuretica.","definition":"<p>Bij een <strong>metabole alkalose</strong> is de HCO<sub>3</sub><sup>−</sup>-concentratie in het bloed verhoogd. Belangrijke oorzaken: verlies van zuur door <em>braken</em> of maagzuigdrainage, gebruik van lis- of thiazidediuretica, hyperaldosteronisme en ernstige hypokaliëmie.</p><p>Volumedepletie houdt de alkalose in stand doordat de nier dan bicarbonaat vasthoudt. De ademhaling compenseert door hypoventilatie (pCO<sub>2</sub> stijgt).</p>","image_url":"","wiki_title":"Metabolic alkalosis","match":"metabole alkalose","option_only":true},"diabetes mellitus":{"title":"Diabetes mellitus","short":"Diabetes mellitus is een chronisch verhoogde bloedglucose door een tekort aan insuline (type 1) of verminderde insulinegevoeligheid met relatief tekort (type 2).","definition":"<p>Bij <strong>diabetes mellitus</strong> is de bloedglucose chronisch te hoog. Bij <em>type 1</em> vernietigt een auto-immuunproces de bètacellen van de pancreas (absoluut insulinetekort, vaak op jonge leeftijd, risico op ketoacidose). Bij <em>type 2</em> is er insulineresistentie (vaak met overgewicht) en een tekortschietende insulineproductie.</p><p>Klachten: dorst, veel plassen, moeheid en gewichtsverlies. Op termijn ontstaan microvasculaire (retinopathie, nefropathie, neuropathie) en macrovasculaire complicaties (hart- en vaatziekten). Diagnose o.a. nuchter glucose ≥7,0 mmol/L of HbA1c ≥48 mmol/mol.</p>","image_url":"","wiki_title":"Diabetes","match":"diabetes mellitus|diabetes|suikerziekte|diabetes mellitus type 2|diabetes mellitus type 1|diabetes mellitus 2","option_only":true},"obesitas":{"title":"Obesitas","short":"Obesitas is ernstig overgewicht (BMI ≥30 kg/m²) met verhoogd risico op diabetes type 2, hart- en vaatziekten, artrose en bepaalde kankers.","definition":"<p>Bij <strong>obesitas</strong> is er een overmaat aan lichaamsvet, gedefinieerd als een <em>BMI ≥30 kg/m²</em>. Vooral vet in de buik (grote middelomtrek, visceraal vet) is metabool ongunstig.</p><p>Obesitas verhoogt het risico op insulineresistentie en diabetes type 2, hypertensie, dyslipidemie, hart- en vaatziekten, slaapapneu, leververvetting, artrose en verschillende vormen van kanker. Oorzaken zijn een combinatie van leefstijl, omgeving, genetische aanleg en soms medicatie of hormonale ziekten.</p>","image_url":"","wiki_title":"Obesity","match":"obesitas|ernstig overgewicht|adipositas","option_only":true},"systemische lupus erythematosus":{"title":"Systemische lupus erythematosus (SLE)","short":"SLE is een systemische auto-immuunziekte met antinucleaire antistoffen en immuuncomplexen; gewrichten, huid, nieren en bloed kunnen aangedaan zijn.","definition":"<p><strong>Systemische lupus erythematosus</strong> is een chronische auto-immuunziekte die vooral jonge vrouwen treft. Er worden antistoffen gevormd tegen kerncomponenten (ANA, anti-dsDNA, anti-Sm), die met antigenen <em>immuuncomplexen</em> vormen die neerslaan in weefsels (type III-reactie) en complement verbruiken.</p><p>Kenmerken: artralgie/artritis, vlindervormig erytheem in het gezicht, fotosensitiviteit, serositis, nefritis, cytopenieën en neurologische verschijnselen. Behandeling met o.a. hydroxychloroquine, corticosteroïden en immunosuppressiva.</p>","image_url":"","wiki_title":"Systemic lupus erythematosus","match":"systemische lupus erythematosus|sle|lupus|systemic lupus erythematosus","option_only":true},"sclerodermie (systemic sclerosis)":{"title":"Systemische sclerose (sclerodermie)","short":"Systemische sclerose is een auto-immuunziekte met fibrose van huid en organen en vaatafwijkingen; typisch zijn Raynaud, strakke huid en anti-Scl-70/anticentromeer.","definition":"<p>Bij <strong>systemische sclerose</strong> (sclerodermie) leiden auto-immuniteit en schade aan kleine bloedvaten tot overmatige collageenvorming en <em>fibrose</em> van huid en inwendige organen.</p><p>Bijna alle patiënten hebben het fenomeen van Raynaud. De huid wordt strak en verdikt (sclerodactylie), en er kunnen slikklachten (oesofagus), longfibrose, pulmonale hypertensie en een renale crisis ontstaan. Bij de beperkte vorm (CREST) zijn vaak anticentromeer-antistoffen aanwezig, bij de diffuse vorm anti-Scl-70 (topo-isomerase I).</p>","image_url":"","wiki_title":"Systemic scleroderma","match":"sclerodermie (systemic sclerosis)|sclerodermie|systemische sclerose|systemic sclerosis","option_only":true},"anemie":{"title":"Anemie","short":"Anemie is een te laag hemoglobinegehalte in het bloed, waardoor het zuurstoftransport vermindert.","definition":"<p>Bij <strong>anemie</strong> is de hemoglobineconcentratie verlaagd (bij volwassenen ongeveer &lt;8,5 mmol/L bij mannen en &lt;7,5 mmol/L bij vrouwen). Klachten: moeheid, kortademigheid bij inspanning, bleekheid en hartkloppingen.</p><p>Indeling op het MCV: <em>microcytair</em> (o.a. ijzergebrek, thalassemie), <em>normocytair</em> (o.a. acuut bloedverlies, chronische ziekte, nierfalen) en <em>macrocytair</em> (o.a. vitamine B12- of foliumzuurtekort). Daarnaast onderscheidt men verminderde aanmaak van versterkte afbraak (hemolyse) of verlies.</p>","image_url":"","wiki_title":"Anemia","match":"anemie|bloedarmoede","option_only":true},"parafraseren":{"title":"Parafraseren (gesprekstechniek)","short":"Parafraseren is het in eigen woorden teruggeven van de inhoud van één uitspraak van de patiënt, om te laten merken dat je luistert en te checken of je het goed begrijpt.","definition":"<p>Bij <strong>parafraseren</strong> herhaalt de arts de <em>inhoud</em> van wat de patiënt net zei in eigen, vaak kortere woorden (bijvoorbeeld: “U heeft dus vooral ’s nachts last”). Het is een vorm van actief luisteren.</p><p>Parafraseren nodigt de patiënt uit om verder te vertellen of te corrigeren. Het verschilt van het reflecteren van gevoelens, dat zich richt op de emotie achter de woorden.</p>","image_url":"","wiki_title":"","match":"parafraseren|parafrase","option_only":true},"gedragsbehoud":{"title":"Gedragsbehoud (stages of change)","short":"Gedragsbehoud is de fase in het model van Prochaska en DiClemente waarin het nieuwe gedrag al langer (meestal >6 maanden) wordt volgehouden.","definition":"<p>Het <strong>transtheoretisch model</strong> (stages of change) van Prochaska en DiClemente beschrijft fasen van gedragsverandering: precontemplatie, contemplatie, preparatie, actie en <strong>gedragsbehoud</strong>; terugval kan op elk moment optreden.</p><p>In de fase van gedragsbehoud heeft iemand het nieuwe gedrag (bijvoorbeeld gestopt met roken) al langer dan ongeveer zes maanden volgehouden. Het accent ligt dan op het voorkomen van terugval.</p>","image_url":"","wiki_title":"","match":"gedragsbehoud|maintenance","option_only":true},"preparatie":{"title":"Preparatie (stages of change)","short":"Preparatie is de fase in het model van Prochaska en DiClemente waarin iemand van plan is binnenkort (binnen ±1 maand) te veranderen en al voorbereidingen treft.","definition":"<p>In het <strong>transtheoretisch model</strong> van gedragsverandering volgt de <strong>preparatiefase</strong> op contemplatie. De persoon heeft besloten om te veranderen, meestal binnen een maand, en zet al kleine stappen: een stopdatum kiezen, informatie zoeken, hulp regelen.</p><p>De volgende fase is actie, waarin het gedrag daadwerkelijk wordt veranderd.</p>","image_url":"","wiki_title":"","match":"preparatie|voorbereidingsfase","option_only":true},"actie":{"title":"Actie (stages of change)","short":"Actie is de fase in het model van Prochaska en DiClemente waarin iemand het gedrag daadwerkelijk heeft veranderd, korter dan ongeveer zes maanden geleden.","definition":"<p>In het <strong>transtheoretisch model</strong> van gedragsverandering is de <strong>actiefase</strong> de periode waarin iemand het nieuwe gedrag actief uitvoert, bijvoorbeeld net gestopt is met roken. Deze fase duurt tot ongeveer zes maanden na de verandering.</p><p>Het risico op terugval is in deze fase groot; ondersteuning richt zich op volhouden en omgaan met verleidingen. Daarna volgt de fase van gedragsbehoud.</p>","image_url":"","wiki_title":"","match":"actie|actiefase","option_only":true},"crp":{"title":"CRP (C-reactief proteïne)","short":"CRP is een acutefase-eiwit uit de lever dat binnen een dag sterk stijgt bij ontsteking of infectie, vooral bacterieel.","definition":"<p><strong>C-reactief proteïne</strong> wordt door de lever gemaakt onder invloed van vooral <em>IL-6</em>. Het bindt aan fosfocholine op micro-organismen en beschadigde cellen en activeert zo complement (opsonisatie).</p><p>Het CRP stijgt binnen 6–12 uur na het begin van een ontsteking en daalt snel bij herstel, waardoor het een nuttige maat is voor ontstekingsactiviteit. Bacteriële infecties geven vaak een hoger CRP dan virale, maar de waarde is niet specifiek.</p>","image_url":"","wiki_title":"C-reactive protein","match":"crp|c-reactief proteïne|c-reactief proteine","option_only":true},"legionella pneumophila":{"title":"Legionella pneumophila","short":"Legionella is een gramnegatieve staaf uit warm water die een ernstige (atypische) pneumonie kan veroorzaken: de veteranenziekte.","definition":"<p><strong><em>Legionella pneumophila</em></strong> groeit in warmwatersystemen, koeltorens en bubbelbaden en wordt via aerosolen ingeademd; er is geen overdracht van mens op mens. Risicofactoren zijn hogere leeftijd, roken en immuunsuppressie. Naast pneumonie kunnen diarree, verwardheid en hyponatriëmie optreden. Diagnose met de urine-antigeentest; bètalactamantibiotica werken niet, macroliden en chinolonen wel.</p>","image_url":"","wiki_title":"Legionella pneumophila","match":"legionella pneumophila|legionella|veteranenziekte","option_only":true},"mycoplasma pneumoniae":{"title":"Mycoplasma pneumoniae","short":"Mycoplasma pneumoniae is een bacterie zonder celwand die bij jongeren een ‘atypische’ pneumonie veroorzaakt.","definition":"<p><strong><em>Mycoplasma pneumoniae</em></strong> heeft geen peptidoglycaanwand en is daardoor ongevoelig voor bètalactamantibiotica en niet zichtbaar met een gramkleuring. Het veroorzaakt vooral bij schoolkinderen en jongvolwassenen een geleidelijk beginnende luchtweginfectie met droge hoest. Er kunnen koude agglutininen (hemolyse) en extrapulmonale verschijnselen optreden. Behandeling met macroliden of doxycycline.</p>","image_url":"","wiki_title":"Mycoplasma pneumoniae","match":"mycoplasma pneumoniae|mycoplasma","option_only":true},"ciprofloxacine":{"title":"Ciprofloxacine","short":"Ciprofloxacine is een fluorochinolon dat het bacteriële DNA-gyrase remt; werkzaam tegen veel gramnegatieve bacteriën.","definition":"<p><strong>Ciprofloxacine</strong> remt DNA-gyrase en topo-isomerase IV, waardoor de bacterie haar DNA niet kan repliceren (bactericide). Het werkt goed tegen gramnegatieve staven, inclusief <em>Pseudomonas</em>, en wordt o.a. gebruikt bij gecompliceerde urineweginfecties en prostatitis. Bijwerkingen: peesruptuur, QT-verlenging, verwardheid en <em>C. difficile</em>-infectie.</p>","image_url":"","wiki_title":"Ciprofloxacin","match":"ciprofloxacine|ciprofloxacin|fluorochinolon","option_only":true},"copd":{"title":"COPD","short":"COPD is een chronische longziekte met niet volledig omkeerbare luchtwegobstructie, meestal door roken.","definition":"<p>Bij <strong>COPD</strong> leiden chronische ontsteking van de kleine luchtwegen en afbraak van alveolewanden (emfyseem) tot een blijvende obstructie: FEV1/FVC &lt; 0,7 na bronchodilatatie. Klachten zijn kortademigheid bij inspanning, chronische hoest en sputum, met periodes van verergering (exacerbaties). Belangrijkste behandeling: stoppen met roken, luchtwegverwijders, beweegprogramma's en vaccinaties.</p>","image_url":"","wiki_title":"Chronic obstructive pulmonary disease","match":"copd|chronic obstructive pulmonary disease|chronisch obstructieve longziekte","option_only":true},"verkoudheid":{"title":"Verkoudheid (common cold)","short":"Een verkoudheid is een virale infectie van neus en keel met niezen, loopneus, keelpijn en soms lichte koorts.","definition":"<p>Een <strong>verkoudheid</strong> wordt meestal veroorzaakt door rhinovirussen, daarnaast door corona-, adeno- en andere virussen. Klachten zijn een verstopte of loopneus, niezen, keelpijn en hoesten, die binnen ongeveer een week tot tien dagen afnemen. De behandeling is symptomatisch; antibiotica hebben geen zin.</p>","image_url":"","wiki_title":"Common cold","match":"verkoudheid|common cold","option_only":true},"longembolie":{"title":"Longembolie","short":"Bij een longembolie sluit een stolsel (meestal uit de beenvenen) een longslagader af, met acute benauwdheid en pijn bij het ademen.","definition":"<p>Een <strong>longembolie</strong> ontstaat meestal door een trombus uit de diepe venen van been of bekken. Risicofactoren volgen de trias van Virchow: stase (immobilisatie), hypercoagulabiliteit (kanker, oestrogenen, zwangerschap, erfelijke trombofilie) en vaatwandschade (operatie, trauma). Klachten: plotselinge dyspneu, pleuritische pijn, tachycardie, soms hemoptoë of collaps. Diagnostiek met een beslisregel, D-dimeer en CT-angiografie; behandeling met antistolling.</p>","image_url":"","wiki_title":"Pulmonary embolism","match":"longembolie|pulmonale embolie|longembolieën","option_only":true},"ct-thorax":{"title":"CT-thorax","short":"Een CT-thorax is een röntgenscan in dwarsdoorsneden van de borstkas, gedetailleerder dan een X-thorax.","definition":"<p>Een <strong>CT-thorax</strong> geeft een driedimensionaal beeld van longen, mediastinum, pleura en thoraxwand. Met intraveneus contrast (CT-angiografie) is het het standaardonderzoek bij verdenking op longembolie. Een hoge-resolutie-CT (HRCT) is geschikt voor interstitiële longziekten; een lage-dosis-CT wordt gebruikt voor screening en follow-up van longnodules.</p>","image_url":"","wiki_title":"CT scan","match":"ct-thorax|ct thorax|ct van de thorax","option_only":true},"sputumkweek":{"title":"Sputumkweek","short":"Bij een sputumkweek wordt opgehoest slijm in het laboratorium gekweekt om de verwekker van een luchtweginfectie en de gevoeligheid voor antibiotica te bepalen.","definition":"<p>Voor een betrouwbare <strong>sputumkweek</strong> moet het materiaal uit de diepere luchtwegen komen en niet vooral uit speeksel (beoordeeld via het aantal plaveiselcellen en leukocyten). Een kweek duurt meestal 1–3 dagen; voor mycobacteriën weken. In de huisartsenpraktijk wordt het weinig gedaan; in het ziekenhuis vooral bij ernstige pneumonie, COPD-exacerbaties en verdenking op tuberculose.</p>","image_url":"","wiki_title":"Sputum culture","match":"sputumkweek|sputum kweek","option_only":true},"ecg":{"title":"ECG (elektrocardiogram)","short":"Een ECG registreert de elektrische activiteit van het hart via elektroden op de huid.","definition":"<p>Een standaard <strong>12-afleidingen-ECG</strong> laat de P-top (boezemdepolarisatie), het QRS-complex (kamerdepolarisatie) en de T-top (repolarisatie) zien. Het wordt gebruikt om ritmestoornissen, geleidingsstoornissen, ischemie en infarct, hypertrofie en elektrolytstoornissen (bijv. hyperkaliëmie) op te sporen.</p>","image_url":"","wiki_title":"Electrocardiography","match":"ecg|elektrocardiogram|ekg","option_only":true},"paroxysmaal atriumfibrilleren":{"title":"Paroxysmaal atriumfibrilleren","short":"Bij paroxysmaal atriumfibrilleren treden aanvallen van boezemfibrilleren op die binnen 7 dagen vanzelf stoppen.","definition":"<p>Bij <strong>atriumfibrilleren</strong> is de elektrische activiteit van de boezems chaotisch; de kamers slaan onregelmatig en vaak snel. In de paroxysmale vorm duren episodes korter dan een week en eindigen ze spontaan. Er is een verhoogd risico op trombo-embolie (vooral herseninfarct) vanuit het linkerhartoor; afhankelijk van de CHA₂DS₂-VASc-score wordt antistolling gegeven.</p>","image_url":"","wiki_title":"Atrial fibrillation","match":"paroxysmaal atriumfibrilleren|paroxysmaal boezemfibrilleren|atriumfibrilleren|boezemfibrilleren","option_only":true},"pericarditis":{"title":"Pericarditis","short":"Pericarditis is een ontsteking van het hartzakje, met scherpe, houdingsafhankelijke pijn op de borst.","definition":"<p><strong>Pericarditis</strong> wordt meestal veroorzaakt door een virus, maar ook door bacteriën, auto-immuunziekten, nierfalen, tumoren of na een hartinfarct of hartoperatie. Typisch zijn scherpe pijn die verergert bij plat liggen en diep inademen, een pericardwrijven en diffuse ST-elevatie op het ECG. Bij veel vocht in het hartzakje kan een harttamponnade ontstaan.</p>","image_url":"","wiki_title":"Pericarditis","match":"pericarditis|hartzakontsteking","option_only":true},"metabole acidose":{"title":"Metabole acidose","short":"Bij een metabole acidose is het bicarbonaat verlaagd en daalt de pH, door ophoping van zuren of verlies van bicarbonaat.","definition":"<p>Een <strong>metabole acidose</strong> wordt ingedeeld met de aniongap. Een <em>verhoogde</em> aniongap past bij ophoping van zuren: lactaat, ketonen (diabetische ketoacidose), nierfalen of intoxicaties (methanol, ethyleenglycol, salicylaten). Een <em>normale</em> aniongap past bij verlies van bicarbonaat via diarree of een renale tubulaire acidose. De ademhaling compenseert met diepe, snelle ademhaling (Kussmaul).</p>","image_url":"","wiki_title":"Metabolic acidosis","match":"metabole acidose","option_only":true},"hypoventilatie":{"title":"Hypoventilatie","short":"Hypoventilatie is te weinig ademen voor de stofwisseling, waardoor het CO₂ in het bloed stijgt (respiratoire acidose).","definition":"<p>Bij <strong>hypoventilatie</strong> daalt de alveolaire ventilatie, met hypercapnie en vaak hypoxemie. Oorzaken zijn een verminderde ademprikkel (opioïden, sedativa, hersenstamletsel), neuromusculaire ziekten, ernstige obesitas, thoraxwandafwijkingen en ernstige COPD. Het lichaam compenseert met renale retentie van bicarbonaat.</p>","image_url":"","wiki_title":"Hypoventilation","match":"hypoventilatie","option_only":true},"hypothyreoïdie":{"title":"Hypothyreoïdie","short":"Hypothyreoïdie is een te trage schildklierwerking, met vermoeidheid, kouwelijkheid, gewichtstoename en obstipatie.","definition":"<p><strong>Hypothyreoïdie</strong> wordt in Nederland meestal veroorzaakt door de auto-immuunziekte van Hashimoto, daarnaast na thyreoïdectomie of radioactief jodium, door medicatie (amiodaron, lithium) of zelden door hypofyse-uitval. Klachten: traagheid, kouwelijkheid, droge huid, gewichtstoename, obstipatie, bradycardie en depressieve klachten. Bij primaire hypothyreoïdie is het TSH verhoogd en het vrij T4 laag; behandeling met levothyroxine.</p>","image_url":"","wiki_title":"Hypothyroidism","match":"hypothyreoïdie|hypothyreoidie|trage schildklier","option_only":true},"overgewicht":{"title":"Overgewicht","short":"Overgewicht is een te hoog lichaamsgewicht ten opzichte van de lengte, gedefinieerd als een BMI tussen 25 en 30 kg/m².","definition":"<p>Bij <strong>overgewicht</strong> (BMI 25–30) en vooral bij obesitas (BMI ≥30) neemt het risico op diabetes type 2, hart- en vaatziekten, artrose en sommige kankers toe. De verdeling van het vet is belangrijk: buikvet (gemeten met de middelomtrek) is metabool ongunstiger dan vet op heupen en bovenbenen.</p>","image_url":"","wiki_title":"Overweight","match":"overgewicht","option_only":true},"reumatoïde artritis":{"title":"Reumatoïde artritis","short":"Reumatoïde artritis is een chronische auto-immuunziekte met symmetrische ontsteking van vooral de kleine gewrichten van handen en voeten.","definition":"<p>Bij <strong>reumatoïde artritis</strong> leidt synovitis tot pannusvorming en erosie van kraakbeen en bot. Kenmerken: symmetrische polyartritis van MCP-, PIP- en MTP-gewrichten, ochtendstijfheid langer dan een uur, reumafactor en anti-CCP-antistoffen. Extra-articulair: reumanoduli, longaandoeningen, vasculitis. Vroege behandeling met DMARD's (zoals methotrexaat) voorkomt gewrichtsschade.</p>","image_url":"","wiki_title":"Rheumatoid arthritis","match":"reumatoïde artritis|reumatoide artritis|reumatoïde arthritis","option_only":true},"polymyalgia reumatica":{"title":"Polymyalgia reumatica","short":"Polymyalgia reumatica is een ontstekingsziekte bij ouderen met pijn en stijfheid in schouder- en heupgordel.","definition":"<p><strong>Polymyalgia reumatica</strong> treft vooral mensen boven de 50, vaker vrouwen. Kenmerkend zijn ochtendstijfheid en pijn in nek, schouders en heupen, met moeite om op te staan of de armen te heffen, en een sterk verhoogde BSE/CRP. Er is geen echte spierzwakte. De ziekte reageert snel op lage dosis prednison en gaat soms samen met reuscelarteriitis.</p>","image_url":"","wiki_title":"Polymyalgia rheumatica","match":"polymyalgia reumatica|polymyalgia rheumatica|pmr","option_only":true},"gevoelsreflectie maken":{"title":"Gevoelsreflectie","short":"Bij een gevoelsreflectie benoemt de arts het gevoel dat hij of zij bij de patiënt waarneemt (‘U lijkt er erg van te schrikken’).","definition":"<p>Een <strong>gevoelsreflectie</strong> richt zich niet op de inhoud maar op de emotie achter de woorden of het gedrag van de patiënt. Door het gevoel te benoemen voelt de patiënt zich begrepen en krijgt hij of zij ruimte om erover te praten. Het verschilt van parafraseren, dat de inhoud teruggeeft.</p>","image_url":"","wiki_title":"","match":"gevoelsreflectie maken|een gevoelsreflectie maken|gevoelsreflectie|reflecteren van gevoelens","option_only":true},"contemplatie":{"title":"Contemplatie (stages of change)","short":"Contemplatie is de fase in het model van Prochaska en DiClemente waarin iemand overweegt het gedrag te veranderen, maar nog twijfelt.","definition":"<p>In het <strong>transtheoretisch model</strong> volgt contemplatie op precontemplatie. De persoon ziet de nadelen van het huidige gedrag, maar weegt die af tegen de voordelen; er is ambivalentie. Een arts kan in deze fase helpen de voor- en nadelen te verkennen, bijvoorbeeld met motiverende gespreksvoering. Daarna volgen preparatie, actie en gedragsbehoud.</p>","image_url":"","wiki_title":"Transtheoretical model","match":"contemplatie","option_only":true},"precontemplatie":{"title":"Precontemplatie (stages of change)","short":"Precontemplatie is de eerste fase in het transtheoretisch model van gedragsverandering (Prochaska en DiClemente).","definition":"<p>Het <strong>transtheoretisch model</strong> beschrijft de fasen precontemplatie, contemplatie, preparatie, actie en gedragsbehoud; terugval kan op elk moment optreden. In de fase van precontemplatie ziet de persoon (nog) geen reden om het eigen gedrag te veranderen. Een arts richt zich in deze fase vooral op informeren en bewustwording.</p>","image_url":"","wiki_title":"Transtheoretical model","match":"precontemplatie","option_only":true},"diagnose-recept model":{"title":"Diagnose-receptmodel","short":"Het diagnose-receptmodel is een arts-gecentreerde manier van consultvoeren waarin de arts diagnose en behandeling bepaalt.","definition":"<p>In het <strong>diagnose-receptmodel</strong> stelt de arts vragen, onderzoekt, stelt een diagnose en schrijft een behandeling voor; de patiënt heeft een vooral passieve rol. Het staat tegenover patiëntgerichte modellen zoals gedeelde besluitvorming, waarin de waarden en voorkeuren van de patiënt meewegen.</p>","image_url":"","wiki_title":"","match":"diagnose-recept model|diagnose-receptmodel|paternalistisch model","option_only":true},"informed decision making model":{"title":"Informed decision making-model","short":"In het informed decision making-model geeft de arts alle informatie en neemt de patiënt zelf de beslissing.","definition":"<p>Bij <strong>informed decision making</strong> is de arts vooral informatieverstrekker en ligt de beslissing volledig bij de goed geïnformeerde patiënt. Het staat tussen het paternalistische model (de arts beslist) en gedeelde besluitvorming (arts en patiënt beslissen samen na uitwisseling van informatie en voorkeuren).</p>","image_url":"","wiki_title":"","match":"informed decision making model|informed decision making|geïnformeerde besluitvorming","option_only":true},"trombolyse":{"title":"Trombolyse","short":"Trombolyse is het oplossen van een stolsel met een middel dat plasminogeen activeert, zoals alteplase.","definition":"<p>Bij <strong>trombolyse</strong> wordt een plasminogeenactivator (bijv. alteplase, tenecteplase) toegediend, waardoor plasmine ontstaat dat fibrine afbreekt. Het wordt gebruikt bij een acuut herseninfarct (binnen 4,5 uur), soms bij een massale longembolie en (als PCI niet snel kan) bij een STEMI. Het belangrijkste risico is een bloeding, waaronder een hersenbloeding.</p>","image_url":"","wiki_title":"Thrombolysis","match":"trombolyse|trombolytica|alteplase","option_only":true},"longtransplantatie":{"title":"Longtransplantatie","short":"Bij een longtransplantatie worden één of beide longen vervangen door donorlongen, bij eindstadium longziekte.","definition":"<p>Een <strong>longtransplantatie</strong> wordt overwogen bij ernstige, progressieve longziekte zonder andere behandelopties, zoals COPD/emfyseem, longfibrose, cystische fibrose en pulmonale arteriële hypertensie. Na transplantatie is levenslang immunosuppressie nodig. Een belangrijke late complicatie is chronische afstoting (bronchiolitis obliterans).</p>","image_url":"","wiki_title":"Lung transplantation","match":"longtransplantatie","option_only":true},"lisdiureticum":{"title":"Lisdiureticum","short":"Lisdiuretica remmen de NKCC2-cotransporter in de lis van Henle en zijn de krachtigste plasmiddelen.","definition":"<p><strong>Lisdiuretica</strong> zoals furosemide remmen de Na⁺/K⁺/2Cl⁻-cotransporter in het dikke opstijgende deel van de lis van Henle. Ze worden gebruikt bij oedeem door hartfalen, nierziekte of levercirrose en bij longoedeem. Bijwerkingen: hypokaliëmie, hyponatriëmie, hypomagnesiëmie, metabole alkalose, uitdroging en ototoxiciteit; anders dan thiaziden verhogen ze de calciumuitscheiding.</p>","image_url":"","wiki_title":"Loop diuretic","match":"lisdiureticum|lisdiuretica|furosemide|bumetanide","option_only":true},"bnp":{"title":"BNP (brain natriuretic peptide)","short":"BNP is een hormoon uit de hartkamers dat vrijkomt bij rek van de wand; een verhoogde waarde past bij hartfalen.","definition":"<p><strong>BNP</strong> en het inactieve NT-proBNP worden afgegeven door ventrikelcellen bij volume- of drukbelasting. BNP bevordert natriurese en vaatverwijding en remt het RAAS. Een normale waarde maakt hartfalen bij een kortademige patiënt onwaarschijnlijk. Ook nierfalen, hoge leeftijd, longembolie en boezemfibrilleren verhogen de waarde.</p>","image_url":"","wiki_title":"Brain natriuretic peptide","match":"bnp|nt-probnp|natriuretisch peptide","option_only":true},"shared decision making model":{"title":"Gedeelde besluitvorming (shared decision making)","short":"Bij gedeelde besluitvorming kiezen arts en patiënt samen een behandeling, op basis van medische informatie en de waarden van de patiënt.","definition":"<p>Bij <strong>shared decision making</strong> doorlopen arts en patiënt stappen: bespreken dat er een keuze is, de opties met voor- en nadelen uitleggen, de voorkeuren en waarden van de patiënt verkennen en samen tot een besluit komen. Het staat tussen het paternalistische model (arts beslist) en het informatieve model (patiënt beslist alleen). Keuzehulpen kunnen het ondersteunen.</p>","image_url":"","wiki_title":"Shared decision-making in medicine","match":"shared decision making model|shared decision making|gedeelde besluitvorming|overlegmodel","option_only":true},"mycobacterium tuberculosis (tuberculose)":{"title":"Mycobacterium tuberculosis","short":"M. tuberculosis is de zuurvaste, langzaam groeiende staafbacterie die tuberculose veroorzaakt.","definition":"<p><strong><em>Mycobacterium tuberculosis</em></strong> is een aerobe staafbacterie met een wasachtige, mycolzuurrijke celwand. Daardoor kleurt hij niet goed met de gramkleuring maar wel met de Ziehl-Neelsenkleuring (<em>zuurvast</em>).</p><p>Hij wordt aerogeen overgedragen, groeit zeer langzaam (weken in kweek) en overleeft in macrofagen. De afweer is vooral cellulair (T-cellen) en leidt tot granulomen met centrale verkazing. Hij veroorzaakt tuberculose.</p>","image_url":"","wiki_title":"Mycobacterium tuberculosis","match":"mycobacterium tuberculosis (tuberculose)","option_only":true},"diabetes mellitus 2":{"title":"Diabetes mellitus","short":"Diabetes mellitus is een chronisch verhoogde bloedglucose door een tekort aan insuline (type 1) of verminderde insulinegevoeligheid met relatief tekort (type 2).","definition":"<p>Bij <strong>diabetes mellitus</strong> is de bloedglucose chronisch te hoog. Bij <em>type 1</em> vernietigt een auto-immuunproces de bètacellen van de pancreas (absoluut insulinetekort, vaak op jonge leeftijd, risico op ketoacidose). Bij <em>type 2</em> is er insulineresistentie (vaak met overgewicht) en een tekortschietende insulineproductie.</p><p>Klachten: dorst, veel plassen, moeheid en gewichtsverlies. Op termijn ontstaan microvasculaire (retinopathie, nefropathie, neuropathie) en macrovasculaire complicaties (hart- en vaatziekten). Diagnose o.a. nuchter glucose ≥7,0 mmol/L of HbA1c ≥48 mmol/mol.</p>","image_url":"","wiki_title":"Diabetes","match":"diabetes mellitus 2","option_only":true},"overmatig alcoholgebruik":{"title":"Alcohol (ethanol)","short":"Ethanol wordt in de lever afgebroken via acetaldehyde tot azijnzuur; overmatig gebruik schaadt lever, brein, hart en pancreas.","definition":"<p><strong>Ethanol</strong> wordt vooral in de lever geoxideerd door <em>alcoholdehydrogenase</em> tot acetaldehyde en daarna door aldehydedehydrogenase tot acetaat. Hierbij ontstaat veel NADH, wat de gluconeogenese remt (hypoglykemie) en vetstapeling in de lever bevordert.</p><p>Chronisch overmatig gebruik geeft leververvetting, alcoholische hepatitis en cirrose, pancreatitis, cardiomyopathie, hypertensie, neuropathie, thiaminetekort (Wernicke-Korsakov) en een verhoogd risico op verschillende kankers.</p>","image_url":"","wiki_title":"Alcohol (drug)","match":"overmatig alcoholgebruik","option_only":true},"sarcoïdose":{"title":"Sarcoïdose","short":"Sarcoïdose is een systemische aandoening van onbekende oorzaak met niet-verkazende granulomen, vooral in longen en lymfeklieren.","definition":"<p>Bij <strong>sarcoïdose</strong> zijn vaak de hilaire lymfeklieren en het longweefsel aangedaan; ook huid (erythema nodosum), ogen (uveïtis), hart en zenuwstelsel kunnen betrokken zijn. Het ACE en calcium kunnen verhoogd zijn. Het syndroom van Löfgren (koorts, erythema nodosum, hilaire klieren, enkelartritis) heeft een goede prognose.</p>","image_url":"","wiki_title":"Sarcoidosis","match":"sarcoïdose|sarcoidose|ziekte van besnier-boeck","option_only":true},"hartfalen":{"title":"Hartfalen","short":"Bij hartfalen kan het hart onvoldoende bloed rondpompen voor de behoefte van het lichaam, met kortademigheid, vermoeidheid en vochtophoping.","definition":"<p><strong>Hartfalen</strong> wordt ingedeeld naar ejectiefractie (verminderd, licht verminderd, behouden). Oorzaken zijn o.a. ischemie, hypertensie, klepziekten en cardiomyopathieën. Klachten: inspanningsdyspneu, orthopneu, oedeem, gewichtstoename. Diagnose met NT-proBNP en echocardiografie. Behandeling bij verminderde EF: ACE-remmer/ARNI, bètablokker, MRA, SGLT2-remmer en diuretica bij overvulling.</p>","image_url":"","wiki_title":"Heart failure","match":"hartfalen|decompensatio cordis|hartinsufficiëntie","option_only":true},"levocetirizine":{"title":"Levocetirizine","short":"Levocetirizine is een tweede generatie H1-antihistaminicum dat weinig sufheid geeft; gebruikt bij hooikoorts en urticaria.","definition":"<p>Tweede generatie <strong>antihistaminica</strong> (cetirizine, levocetirizine, loratadine) blokkeren H1-receptoren en passeren de bloed-hersenbarrière nauwelijks, waardoor ze minder sederend en anticholinerg zijn dan de eerste generatie (zoals clemastine). Ze verminderen jeuk, niezen, waterige neus en netelroos.</p>","image_url":"","wiki_title":"Levocetirizine","match":"levocetirizine|cetirizine|antihistaminicum|antihistaminica","option_only":true},"troponine t":{"title":"Troponine","short":"Troponine is een eiwit uit de hartspier; een stijging in het bloed wijst op schade aan hartspiercellen.","definition":"<p><strong>Cardiaal troponine</strong> (T of I) komt vrij bij beschadiging van myocyten. Het is de belangrijkste marker voor een myocardinfarct: het stijgt binnen enkele uren en blijft dagen verhoogd. Ook bij myocarditis, longembolie, hartfalen, sepsis, nierfalen en na zware inspanning kan het stijgen. Met hooggevoelige tests wordt naar de verandering in de tijd gekeken.</p>","image_url":"","wiki_title":"Troponin","match":"troponine t|troponine|troponine i|hs-troponine","option_only":true},"langwerkende luchtwegverwijder (laba)":{"title":"LABA (langwerkende β2-agonist)","short":"LABA's zijn langwerkende β2-agonisten (zoals formoterol en salmeterol) die de luchtwegen tot 12–24 uur verwijden.","definition":"<p>Een <strong>LABA</strong> stimuleert β2-receptoren in de gladde spier van de luchtwegen. Bij astma worden ze altijd gecombineerd met een inhalatiecorticosteroïd (monotherapie verhoogt het risico op ernstige aanvallen); bij COPD worden ze vaak gecombineerd met een LAMA. Bijwerkingen: tremor, hartkloppingen en hypokaliëmie.</p>","image_url":"","wiki_title":"Long-acting beta-adrenoceptor agonist","match":"langwerkende luchtwegverwijder (laba)|laba|formoterol|salmeterol","option_only":true},"salbutamol vernevelen":{"title":"Salbutamol","short":"Salbutamol is een kortwerkende β2-agonist die binnen minuten de luchtwegen verwijdt; gebruikt bij astma- en COPD-aanvallen.","definition":"<p><strong>Salbutamol</strong> ontspant de gladde spier van de bronchi via β2-receptoren en cAMP. Het werkt binnen enkele minuten en ongeveer 4–6 uur. Het wordt via een dosisaerosol met voorzetkamer of als verneveling gegeven. Bijwerkingen: tremor, tachycardie en een daling van het kalium (het wordt daarom ook gebruikt bij hyperkaliëmie).</p>","image_url":"","wiki_title":"Salbutamol","match":"salbutamol vernevelen|salbutamol verneveling|salbutamol|saba|kortwerkende luchtwegverwijder","option_only":true},"chronisch vermoeidheidssyndroom":{"title":"Chronisch vermoeidheidssyndroom (ME/CVS)","short":"Het chronisch vermoeidheidssyndroom kenmerkt zich door langdurige, invaliderende vermoeidheid die verergert na inspanning, zonder verklarende lichamelijke ziekte.","definition":"<p>Bij <strong>ME/CVS</strong> duurt de vermoeidheid minstens zes maanden en gaat ze samen met een verergering na lichte inspanning (post-exertionele malaise), niet-verkwikkende slaap en cognitieve klachten, soms met orthostatische intolerantie. Andere oorzaken van vermoeidheid moeten worden uitgesloten. Behandeling is gericht op het doseren van activiteit en symptoombestrijding.</p>","image_url":"","wiki_title":"Myalgic encephalomyelitis/chronic fatigue syndrome","match":"chronisch vermoeidheidssyndroom|me/cvs|myalgische encefalomyelitis","option_only":true},"jetlag":{"title":"Jetlag","short":"Jetlag is een tijdelijke ontregeling van de biologische klok na snel reizen over meerdere tijdzones.","definition":"<p>Bij <strong>jetlag</strong> loopt het interne dag-nachtritme (gestuurd door de nucleus suprachiasmaticus) niet gelijk met de lokale tijd. Klachten: slecht slapen, slaperigheid overdag, concentratieproblemen en maag-darmklachten. Aanpassing gaat ongeveer een dag per tijdzone, sneller met daglicht op het juiste moment; melatonine kan helpen.</p>","image_url":"","wiki_title":"Jet lag","match":"jetlag","option_only":true},"ploegendienst":{"title":"Ploegendienst","short":"Werken in ploegendienst verstoort het dag-nachtritme en hangt samen met slaapproblemen en een verhoogd risico op sommige ziekten.","definition":"<p>Bij <strong>ploegenarbeid</strong> en nachtwerk moet het lichaam actief zijn als de biologische klok op rust staat. Dat geeft slaaptekort en vermoeidheid en hangt op lange termijn samen met een verhoogd risico op hart- en vaatziekten, metabole stoornissen en mogelijk borstkanker. Voorwaarts roterende roosters belasten minder.</p>","image_url":"","wiki_title":"Shift work","match":"ploegendienst|nachtdienst|ploegenarbeid","option_only":true},"diffusiestoornis":{"title":"Diffusiestoornis","short":"Bij een diffusiestoornis gaat zuurstof minder goed van de alveoli naar het bloed, door verdikking van de membraan of verlies van oppervlak.","definition":"<p>Een <strong>diffusiestoornis</strong> wordt gemeten met de DLCO (koolmonoxide-diffusiecapaciteit). Ze komt voor bij interstitiële longziekten (verdikte alveolaire wand), emfyseem (verlies van oppervlak), pulmonale hypertensie en anemie. De hypoxemie wordt vaak pas duidelijk bij inspanning, omdat het bloed dan korter in de capillair verblijft.</p>","image_url":"","wiki_title":"Diffusing capacity for carbon monoxide","match":"diffusiestoornis|diffusiebeperking|verminderde diffusiecapaciteit","option_only":true},"ventilatie perfusie mismatch":{"title":"Ventilatie-perfusiemismatch","short":"Bij een ventilatie-perfusiemismatch passen luchtstroom en bloedstroom in delen van de long niet bij elkaar; dat is de belangrijkste oorzaak van hypoxemie.","definition":"<p>Gebieden met wel bloed maar te weinig ventilatie (lage V/Q, ‘relatieve shunt’, bijv. pneumonie, atelectase, astma) leveren zuurstofarm bloed. Gebieden met ventilatie maar weinig bloed (hoge V/Q, dode ruimte, bijv. longembolie) dragen niet bij aan de gaswisseling. Extra zuurstof verbetert hypoxemie door V/Q-mismatch goed, in tegenstelling tot een echte shunt.</p>","image_url":"","wiki_title":"Ventilation/perfusion ratio","match":"ventilatie perfusie mismatch|ventilatie-perfusiemismatch|v/q-mismatch|relatieve shunt","option_only":true},"cryptogene organiserende pneumonie":{"title":"Cryptogene organiserende pneumonie (COP)","short":"COP is een interstitiële longziekte waarbij bindweefselproppen in de kleine luchtwegen en alveoli ontstaan, met een griepachtig beeld en infiltraten die niet op antibiotica reageren.","definition":"<p>Bij <strong>organiserende pneumonie</strong> vullen proppen granulatieweefsel de alveolaire ruimtes. Zonder aanwijsbare oorzaak heet het cryptogeen; secundaire vormen komen voor na infecties, bij bindweefselziekten en door medicatie of bestraling. Klachten: subacuut hoesten, koorts en kortademigheid; de CT toont vaak wisselende consolidaties. Het reageert goed op corticosteroïden.</p>","image_url":"","wiki_title":"Cryptogenic organizing pneumonia","match":"cryptogene organiserende pneumonie|cryptogenic organizing pneumonia","option_only":true},"alveolair proteïnose":{"title":"Pulmonale alveolaire proteïnose","short":"Bij alveolaire proteïnose hoopt surfactant zich op in de alveoli, doordat macrofagen het onvoldoende opruimen.","definition":"<p>De meeste gevallen van <strong>pulmonale alveolaire proteïnose</strong> zijn auto-immuun: antistoffen tegen GM-CSF verstoren de functie van alveolaire macrofagen. Er ontstaat geleidelijk kortademigheid; de CT toont een ‘crazy paving’-patroon. Behandeling met een totale longspoeling of inhalatie van GM-CSF.</p>","image_url":"","wiki_title":"Pulmonary alveolar proteinosis","match":"alveolair proteïnose|alveolaire proteïnose|pulmonale alveolaire proteïnose","option_only":true},"langerhanscel histiocytose":{"title":"Langerhanscelhistiocytose","short":"Langerhanscelhistiocytose is een ziekte waarbij dendritische (Langerhans-achtige) cellen woekeren in o.a. bot, huid en longen.","definition":"<p>Bij <strong>langerhanscelhistiocytose</strong> (vaak met een BRAF-mutatie) ontstaan haarden van CD1a-positieve cellen. Bij kinderen gaat het vaak om botlaesies of een multisysteemziekte; bij volwassenen (vooral rokers) kan een pulmonale vorm ontstaan met noduli en cysten in de bovenvelden. Stoppen met roken kan de longvorm doen verbeteren.</p>","image_url":"","wiki_title":"Langerhans cell histiocytosis","match":"langerhanscel histiocytose|langerhanscelhistiocytose","option_only":true},"mitochondriële myopathie":{"title":"Mitochondriële myopathie","short":"Een mitochondriële myopathie is een spierziekte door een stoornis in de energieproductie van mitochondriën.","definition":"<p>Bij <strong>mitochondriële ziekten</strong> ligt de oorzaak in mitochondriaal DNA (maternaal overerfd) of in kerngenen. Spieren en hersenen, die veel energie gebruiken, zijn vaak aangedaan: inspanningsintolerantie, ptosis en oogspierverlamming, zwakte en lactaatacidose. In het spierbiopt zijn ‘ragged red fibers’ te zien.</p>","image_url":"","wiki_title":"Mitochondrial myopathy","match":"mitochondriële myopathie|mitochondriale myopathie|mitochondriële ziekte","option_only":true},"paniekaanval":{"title":"Paniekaanval","short":"Een paniekaanval is een plotselinge golf van intense angst met lichamelijke klachten, die binnen minuten een piek bereikt.","definition":"<p>Tijdens een <strong>paniekaanval</strong> ontstaan o.a. hartkloppingen, zweten, trillen, benauwdheid, druk op de borst, duizeligheid, tintelingen en angst om dood te gaan of gek te worden. Bij een <strong>paniekstoornis</strong> zijn er herhaalde, onverwachte aanvallen met aanhoudende angst voor nieuwe aanvallen. Behandeling met cognitieve gedragstherapie en/of SSRI's.</p>","image_url":"","wiki_title":"Panic attack","match":"paniekaanval|paniekstoornis","option_only":true},"het diagnose-recept model":{"title":"Diagnose-receptmodel","short":"Het diagnose-receptmodel is een arts-gecentreerde manier van consultvoeren waarin de arts diagnose en behandeling bepaalt.","definition":"<p>In het <strong>diagnose-receptmodel</strong> stelt de arts vragen, onderzoekt, stelt een diagnose en schrijft een behandeling voor; de patiënt heeft een vooral passieve rol. Het staat tegenover patiëntgerichte modellen zoals gedeelde besluitvorming, waarin de waarden en voorkeuren van de patiënt meewegen.</p>","image_url":"","wiki_title":"","match":"het diagnose-recept model","option_only":true},"een myocardinfarct":{"title":"Myocardinfarct","short":"Bij een myocardinfarct sterft hartspierweefsel af doordat een kransslagader (meestal door een trombus op een gescheurde plaque) afsluit.","definition":"<p>Een <strong>myocardinfarct</strong> ontstaat meestal doordat een atherosclerotische plaque in een coronairarterie scheurt, waarna een trombus het vat (deels) afsluit. Het hartspierweefsel achter de afsluiting raakt ischemisch en gaat na 20–30 minuten necrotisch.</p><p>Klachten: drukkende pijn op de borst, uitstralend naar arm, kaak of rug, met zweten, misselijkheid en benauwdheid. Diagnose op basis van klachten, ECG (ST-elevatie of niet) en een stijging van troponine. Complicaties zijn ritmestoornissen, hartfalen en mechanische complicaties. Snelle reperfusie (PCI) is cruciaal.</p>","image_url":"","wiki_title":"Myocardial infarction","match":"een myocardinfarct","option_only":true},"doorgemaakt mi":{"title":"Myocardinfarct","short":"Bij een myocardinfarct sterft hartspierweefsel af doordat een kransslagader (meestal door een trombus op een gescheurde plaque) afsluit.","definition":"<p>Een <strong>myocardinfarct</strong> ontstaat meestal doordat een atherosclerotische plaque in een coronairarterie scheurt, waarna een trombus het vat (deels) afsluit. Het hartspierweefsel achter de afsluiting raakt ischemisch en gaat na 20–30 minuten necrotisch.</p><p>Klachten: drukkende pijn op de borst, uitstralend naar arm, kaak of rug, met zweten, misselijkheid en benauwdheid. Diagnose op basis van klachten, ECG (ST-elevatie of niet) en een stijging van troponine. Complicaties zijn ritmestoornissen, hartfalen en mechanische complicaties. Snelle reperfusie (PCI) is cruciaal.</p>","image_url":"","wiki_title":"Myocardial infarction","match":"doorgemaakt mi","option_only":true},"myocardinfarcering":{"title":"Myocardinfarct","short":"Bij een myocardinfarct sterft hartspierweefsel af doordat een kransslagader (meestal door een trombus op een gescheurde plaque) afsluit.","definition":"<p>Een <strong>myocardinfarct</strong> ontstaat meestal doordat een atherosclerotische plaque in een coronairarterie scheurt, waarna een trombus het vat (deels) afsluit. Het hartspierweefsel achter de afsluiting raakt ischemisch en gaat na 20–30 minuten necrotisch.</p><p>Klachten: drukkende pijn op de borst, uitstralend naar arm, kaak of rug, met zweten, misselijkheid en benauwdheid. Diagnose op basis van klachten, ECG (ST-elevatie of niet) en een stijging van troponine. Complicaties zijn ritmestoornissen, hartfalen en mechanische complicaties. Snelle reperfusie (PCI) is cruciaal.</p>","image_url":"","wiki_title":"Myocardial infarction","match":"myocardinfarcering","option_only":true},"reumatoide artritis":{"title":"Reumatoïde artritis","short":"Reumatoïde artritis is een chronische auto-immuunziekte met symmetrische ontsteking van vooral de kleine gewrichten van handen en voeten.","definition":"<p>Bij <strong>reumatoïde artritis</strong> leidt synovitis tot pannusvorming en erosie van kraakbeen en bot. Kenmerken: symmetrische polyartritis van MCP-, PIP- en MTP-gewrichten, ochtendstijfheid langer dan een uur, reumafactor en anti-CCP-antistoffen. Extra-articulair: reumanoduli, longaandoeningen, vasculitis. Vroege behandeling met DMARD's (zoals methotrexaat) voorkomt gewrichtsschade.</p>","image_url":"","wiki_title":"Rheumatoid arthritis","match":"reumatoide artritis","option_only":true},"sarco&iuml;dose":{"title":"Sarcoïdose","short":"Sarcoïdose is een systemische aandoening van onbekende oorzaak met niet-verkazende granulomen, vooral in longen en lymfeklieren.","definition":"<p>Bij <strong>sarcoïdose</strong> zijn vaak de hilaire lymfeklieren en het longweefsel aangedaan; ook huid (erythema nodosum), ogen (uveïtis), hart en zenuwstelsel kunnen betrokken zijn. Het ACE en calcium kunnen verhoogd zijn. Het syndroom van Löfgren (koorts, erythema nodosum, hilaire klieren, enkelartritis) heeft een goede prognose.</p>","image_url":"","wiki_title":"Sarcoidosis","match":"sarco&iuml;dose","option_only":true},"diclofenac (nsaid)":{"title":"NSAID's","short":"NSAID's remmen cyclo-oxygenase en daarmee de vorming van prostaglandinen; ze werken pijnstillend, koortsverlagend en ontstekingsremmend.","definition":"<p><strong>NSAID's</strong> (zoals ibuprofen, naproxen, diclofenac) remmen COX-1 en COX-2. Door remming van beschermende prostaglandinen kunnen ze maagulcera en bloedingen geven, vooral bij ouderen; ook kunnen ze de nierfunctie verslechteren, de bloeddruk verhogen, hartfalen verergeren en het risico op hart- en vaatziekten iets verhogen. Selectieve COX-2-remmers geven minder maagschade.</p>","image_url":"","wiki_title":"Nonsteroidal anti-inflammatory drug","match":"diclofenac (nsaid)","option_only":true},"beenvarices":{"title":"Varices (spataderen)","short":"Varices zijn verwijde, kronkelige oppervlakkige venen in de benen, door lekkende kleppen.","definition":"<p><strong>Spataderen</strong> komen veel voor, vaker bij vrouwen, met familiaire aanleg, zwangerschap, overgewicht en staand werk als risicofactoren. Klachten: zware, moeë benen, jeuk en oedeem; complicaties zijn tromboflebitis, bloedingen, huidveranderingen en een ulcus cruris. Behandeling: compressie, sclerotherapie, endoveneuze ablatie.</p>","image_url":"","wiki_title":"Varicose veins","match":"beenvarices|varices|spataderen","option_only":true},"klebsiella spp":{"title":"Klebsiella pneumoniae","short":"K. pneumoniae is een gramnegatieve staaf met een dik kapsel die urineweginfecties en (ziekenhuis)pneumonie veroorzaakt.","definition":"<p><strong><em>Klebsiella pneumoniae</em></strong> is een gramnegatieve staaf uit de <em>Enterobacteriaceae</em> met een dik polysacharidekapsel, waardoor kolonies slijmerig zijn.</p><p>Hij veroorzaakt urineweginfecties, sepsis en pneumonie, vooral bij ouderen, alcoholisten en patiënten met diabetes of in het ziekenhuis. Klebsiella is berucht om antibioticaresistentie (ESBL- en carbapenemaseproducerende stammen).</p>","image_url":"","wiki_title":"Klebsiella pneumoniae","match":"klebsiella spp","option_only":true},"een antihistaminicum":{"title":"Levocetirizine","short":"Levocetirizine is een tweede generatie H1-antihistaminicum dat weinig sufheid geeft; gebruikt bij hooikoorts en urticaria.","definition":"<p>Tweede generatie <strong>antihistaminica</strong> (cetirizine, levocetirizine, loratadine) blokkeren H1-receptoren en passeren de bloed-hersenbarrière nauwelijks, waardoor ze minder sederend en anticholinerg zijn dan de eerste generatie (zoals clemastine). Ze verminderen jeuk, niezen, waterige neus en netelroos.</p>","image_url":"","wiki_title":"Levocetirizine","match":"een antihistaminicum","option_only":true},"een beta-agonist":{"title":"Salbutamol","short":"Salbutamol is een kortwerkende β2-agonist die binnen minuten de luchtwegen verwijdt; gebruikt bij astma- en COPD-aanvallen.","definition":"<p><strong>Salbutamol</strong> ontspant de gladde spier van de bronchi via β2-receptoren en cAMP. Het werkt binnen enkele minuten en ongeveer 4–6 uur. Het wordt via een dosisaerosol met voorzetkamer of als verneveling gegeven. Bijwerkingen: tremor, tachycardie en een daling van het kalium (het wordt daarom ook gebruikt bij hyperkaliëmie).</p>","image_url":"","wiki_title":"Salbutamol","match":"een beta-agonist","option_only":true},"v/q scan":{"title":"Ventilatie-perfusiescan","short":"Een ventilatie-perfusiescan vergelijkt met radioactieve stoffen de luchtverdeling en de doorbloeding van de longen, bijv. bij verdenking op longembolie.","definition":"<p>Bij een longembolie toont de <strong>V/Q-scan</strong> gebieden met normale ventilatie maar uitgevallen perfusie (‘mismatch’). Het wordt gebruikt als CT-angiografie niet kan (contrastallergie, nierfunctie, zwangerschap) en bij chronische trombo-embolische pulmonale hypertensie.</p>","image_url":"","wiki_title":"Ventilation/perfusion scan","match":"v/q scan|ventilatie-perfusiescan|longscintigrafie","option_only":true},"lactaat dehydrogenase (ldh)":{"title":"Lactaatdehydrogenase (LDH)","short":"LDH is een enzym in vrijwel alle cellen dat pyruvaat en lactaat in elkaar omzet; een verhoogde bloedwaarde wijst op celschade.","definition":"<p><strong>Lactaatdehydrogenase</strong> zet pyruvaat om in lactaat (en omgekeerd) en regenereert daarbij NAD⁺, wat anaerobe glycolyse mogelijk maakt. In het bloed is LDH een aspecifieke marker van weefselschade: het is verhoogd bij hemolyse, myocardinfarct, leverschade, spierschade en snelgroeiende tumoren zoals lymfomen.</p>","image_url":"","wiki_title":"Lactate dehydrogenase","match":"lactaat dehydrogenase (ldh)","option_only":true},"amoxycilline":{"title":"Amoxicilline","short":"Amoxicilline is een breedspectrum-penicilline die ook een deel van de gramnegatieve bacteriën dekt; veel gebruikt bij luchtweginfecties.","definition":"<p><strong>Amoxicilline</strong> is een aminopenicilline: een bètalactamantibioticum dat de celwandsynthese remt. Het spectrum is breder dan penicilline en omvat ook o.a. <em>H. influenzae</em> en <em>E. coli</em> (mits geen bètalactamase).</p><p>Het is in de huisartsenpraktijk eerste keus bij pneumonie en wordt ook gebruikt bij otitis en sinusitis. Met clavulaanzuur (amoxicilline-clavulaanzuur) is het ook werkzaam tegen bètalactamasevormers.</p>","image_url":"","wiki_title":"Amoxicillin","match":"amoxycilline","option_only":true},"amoxycilline oraal":{"title":"Amoxicilline","short":"Amoxicilline is een breedspectrum-penicilline die ook een deel van de gramnegatieve bacteriën dekt; veel gebruikt bij luchtweginfecties.","definition":"<p><strong>Amoxicilline</strong> is een aminopenicilline: een bètalactamantibioticum dat de celwandsynthese remt. Het spectrum is breder dan penicilline en omvat ook o.a. <em>H. influenzae</em> en <em>E. coli</em> (mits geen bètalactamase).</p><p>Het is in de huisartsenpraktijk eerste keus bij pneumonie en wordt ook gebruikt bij otitis en sinusitis. Met clavulaanzuur (amoxicilline-clavulaanzuur) is het ook werkzaam tegen bètalactamasevormers.</p>","image_url":"","wiki_title":"Amoxicillin","match":"amoxycilline oraal","option_only":true},"claudicatio intermittens":{"title":"Claudicatio intermittens","short":"Claudicatio intermittens is pijn in de kuit of bil bij lopen die bij stilstaan verdwijnt, door perifeer arterieel vaatlijden.","definition":"<p>Bij <strong>claudicatio</strong> zijn de beenarteriën vernauwd door atherosclerose. De enkel-armindex is verlaagd (&lt;0,9). Behandeling: stoppen met roken, gesuperviseerde looptraining, een plaatjesremmer en statine; bij ernstige klachten of kritieke ischemie (rustpijn, wonden) revascularisatie.</p>","image_url":"","wiki_title":"Intermittent claudication","match":"claudicatio intermittens|etalagebenen|perifeer arterieel vaatlijden","option_only":true},"hyperventilatie":{"title":"Hyperventilatie","short":"Bij hyperventilatie wordt meer geademd dan nodig is, waardoor het CO₂ daalt (respiratoire alkalose) met tintelingen en duizeligheid.","definition":"<p>Een <strong>hyperventilatieaanval</strong> kan worden uitgelokt door angst of paniek en geeft tintelingen rond de mond en in de vingers, duizeligheid, benauwdheid en soms carpopedale spasmen. Hyperventilatie kan ook compensatoir zijn (metabole acidose) of door hypoxie, pijn of koorts ontstaan; die oorzaken moeten worden uitgesloten.</p>","image_url":"","wiki_title":"Hyperventilation","match":"hyperventilatie|chronisch hyperventileren","option_only":true},"moraxella catarrhalis":{"title":"Moraxella catarrhalis","short":"Moraxella catarrhalis is een gramnegatieve diplokok die otitis media, sinusitis en COPD-exacerbaties veroorzaakt.","definition":"<p><strong><em>M. catarrhalis</em></strong> maakt bijna altijd bètalactamase, waardoor amoxicilline alleen vaak niet werkt; amoxicilline-clavulaanzuur, macroliden of doxycycline wel.</p>","image_url":"","wiki_title":"Moraxella catarrhalis","match":"moraxella catarrhalis|moraxella","option_only":true},"coronair angiografie":{"title":"Coronairangiografie","short":"Bij coronairangiografie worden de kransslagaders met contrast en röntgen in beeld gebracht via een katheter in de pols of lies.","definition":"<p>Een <strong>CAG</strong> toont vernauwingen in de kransslagaders en wordt vaak direct gecombineerd met een PCI (dotteren en stenten). Complicaties zijn bloedingen op de punctieplaats, contrastnefropathie en zelden een beroerte of infarct.</p>","image_url":"","wiki_title":"Coronary catheterization","match":"coronair angiografie|coronairangiografie|hartkatheterisatie|cag","option_only":true},"decompensatio cordis":{"title":"Hartfalen","short":"Bij hartfalen kan het hart onvoldoende bloed rondpompen voor de behoefte van het lichaam, met kortademigheid, vermoeidheid en vochtophoping.","definition":"<p><strong>Hartfalen</strong> wordt ingedeeld naar ejectiefractie (verminderd, licht verminderd, behouden). Oorzaken zijn o.a. ischemie, hypertensie, klepziekten en cardiomyopathieën. Klachten: inspanningsdyspneu, orthopneu, oedeem, gewichtstoename. Diagnose met NT-proBNP en echocardiografie. Behandeling bij verminderde EF: ACE-remmer/ARNI, bètablokker, MRA, SGLT2-remmer en diuretica bij overvulling.</p>","image_url":"","wiki_title":"Heart failure","match":"decompensatio cordis","option_only":true},"acuut myocardinfarct":{"title":"Myocardinfarct","short":"Bij een myocardinfarct sterft hartspierweefsel af doordat een kransslagader (meestal door een trombus op een gescheurde plaque) afsluit.","definition":"<p>Een <strong>myocardinfarct</strong> ontstaat meestal doordat een atherosclerotische plaque in een coronairarterie scheurt, waarna een trombus het vat (deels) afsluit. Het hartspierweefsel achter de afsluiting raakt ischemisch en gaat na 20–30 minuten necrotisch.</p><p>Klachten: drukkende pijn op de borst, uitstralend naar arm, kaak of rug, met zweten, misselijkheid en benauwdheid. Diagnose op basis van klachten, ECG (ST-elevatie of niet) en een stijging van troponine. Complicaties zijn ritmestoornissen, hartfalen en mechanische complicaties. Snelle reperfusie (PCI) is cruciaal.</p>","image_url":"","wiki_title":"Myocardial infarction","match":"acuut myocardinfarct","option_only":true},"conventionele x-thorax":{"title":"X-thorax","short":"Een X-thorax is een röntgenfoto van de borstkas; het eerste beeldvormend onderzoek bij verdenking op longafwijkingen, hartfalen of pneumothorax.","definition":"<p>Een <strong>X-thorax</strong> is een röntgenopname van de borstkas, meestal posterieur-anterieur en lateraal. Lucht is zwart, weke delen grijs en bot wit.</p><p>Het is snel, goedkoop en met een lage stralingsdosis, en wordt gebruikt om o.a. pneumonie (infiltraat), pleuravocht, pneumothorax, longtumoren, hartvergroting en tekenen van hartfalen op te sporen. Kleine of subtiele afwijkingen zijn er minder goed op te zien dan op een CT.</p>","image_url":"","wiki_title":"Chest radiograph","match":"conventionele x-thorax","option_only":true},"bronchoconstrictie door inspanning":{"title":"Inspanningsastma","short":"Bij inspanningsastma ontstaat tijdens of kort na inspanning een vernauwing van de luchtwegen, met kortademigheid en piepen.","definition":"<p>Bij <strong>inspanningsgebonden bronchoconstrictie</strong> koelen en drogen de luchtwegen uit door de snelle ademhaling, wat mestcellen activeert. Koude, droge lucht verergert het. Een kortwerkende β2-agonist vóór inspanning en een goede onderhoudsbehandeling van astma voorkomen klachten.</p>","image_url":"","wiki_title":"Exercise-induced bronchoconstriction","match":"bronchoconstrictie door inspanning","option_only":true},"echocardiografie (echo hart)":{"title":"Echocardiografie","short":"Echocardiografie is een echo van het hart, waarmee structuur, kleppen en pompfunctie worden beoordeeld.","definition":"<p>Met <strong>echocardiografie</strong> worden o.a. de ejectiefractie, wanddikte, klepafwijkingen, pericardvocht en aangeboren afwijkingen beoordeeld. Een transoesofageale echo geeft betere beelden van kleppen en het linkerhartoor (endocarditis, stolsels).</p>","image_url":"","wiki_title":"Echocardiography","match":"echocardiografie (echo hart)","option_only":true},"elektrocardiogram (ecg)":{"title":"ECG (elektrocardiogram)","short":"Een ECG registreert de elektrische activiteit van het hart via elektroden op de huid.","definition":"<p>Een standaard <strong>12-afleidingen-ECG</strong> laat de P-top (boezemdepolarisatie), het QRS-complex (kamerdepolarisatie) en de T-top (repolarisatie) zien. Het wordt gebruikt om ritmestoornissen, geleidingsstoornissen, ischemie en infarct, hypertrofie en elektrolytstoornissen (bijv. hyperkaliëmie) op te sporen.</p>","image_url":"","wiki_title":"Electrocardiography","match":"elektrocardiogram (ecg)","option_only":true},"q-koorts (coxiella burnetii)":{"title":"Q-koorts (Coxiella burnetii)","short":"Q-koorts is een zoönose door Coxiella burnetii, verspreid via stof van besmette geiten en schapen.","definition":"<p><strong>Q-koorts</strong> geeft vaak een griepachtig beeld, pneumonie of hepatitis; chronische Q-koorts kan endocarditis en vaatinfecties geven, vooral bij klepafwijkingen of vaatprothesen. In 2007–2010 was er in Nederland een grote epidemie rond geitenhouderijen. Behandeling met doxycycline.</p>","image_url":"","wiki_title":"Q fever","match":"q-koorts (coxiella burnetii)|q-koorts|coxiella burnetii","option_only":true},"beroepsastma":{"title":"Beroepsastma","short":"Beroepsastma is astma dat door stoffen op het werk ontstaat, zoals meelstof bij bakkers of isocyanaten bij spuiters.","definition":"<p>Typisch voor <strong>beroepsastma</strong> zijn klachten die verbeteren in het weekend en de vakanties. Vroeg stoppen met blootstelling geeft de beste kans op herstel. Het is een beroepsziekte die moet worden gemeld.</p>","image_url":"","wiki_title":"Occupational asthma","match":"beroepsastma|door werk verergerd astma","option_only":true},"haemophilus influenza type b":{"title":"Haemophilus influenzae","short":"H. influenzae is een kleine gramnegatieve staaf die luchtweginfecties, otitis en (vroeger vaak) meningitis en epiglottitis bij kinderen veroorzaakt.","definition":"<p><strong><em>Haemophilus influenzae</em></strong> is een kleine, gramnegatieve coccobacil. Ondanks de naam veroorzaakt hij geen influenza (dat is een virus).</p><p>Onomkapselde stammen veroorzaken otitis media, sinusitis en exacerbaties van COPD. Het omkapselde type b (Hib) veroorzaakte vroeger veel meningitis en epiglottitis bij jonge kinderen; sinds de Hib-vaccinatie is dat zeldzaam.</p>","image_url":"","wiki_title":"Haemophilus influenzae","match":"haemophilus influenza type b","option_only":true},"tuberculose (mycobacterium tuberculosis)":{"title":"Tuberculose","short":"Tuberculose is een infectie met Mycobacterium tuberculosis, meestal in de longen, met langdurig hoesten, nachtzweten, gewichtsverlies en granulomen.","definition":"<p><strong>Tuberculose</strong> wordt veroorzaakt door <em>Mycobacterium tuberculosis</em> en verspreidt zich via aerosolen. Na infectie wordt de bacterie meestal ingekapseld in granulomen (latente tbc); bij verminderde afweer kan actieve ziekte ontstaan.</p><p>Longtuberculose geeft langdurig hoesten (soms met bloed), koorts, nachtzweten en gewichtsverlies; typisch zijn holtevorming in de longtoppen en granulomen met centrale <em>verkazing</em>. Behandeling met een combinatie van tuberculostatica gedurende minstens 6 maanden.</p>","image_url":"","wiki_title":"Tuberculosis","match":"tuberculose (mycobacterium tuberculosis)","option_only":true},"legionellose (legionella pneumophila)":{"title":"Legionella pneumophila","short":"Legionella is een gramnegatieve staaf uit warm water die een ernstige (atypische) pneumonie kan veroorzaken: de veteranenziekte.","definition":"<p><strong><em>Legionella pneumophila</em></strong> groeit in warmwatersystemen, koeltorens en bubbelbaden en wordt via aerosolen ingeademd; er is geen overdracht van mens op mens. Risicofactoren zijn hogere leeftijd, roken en immuunsuppressie. Naast pneumonie kunnen diarree, verwardheid en hyponatriëmie optreden. Diagnose met de urine-antigeentest; bètalactamantibiotica werken niet, macroliden en chinolonen wel.</p>","image_url":"","wiki_title":"Legionella pneumophila","match":"legionellose (legionella pneumophila)","option_only":true},"een beta-2-sympaticomimeticum":{"title":"Salbutamol","short":"Salbutamol is een kortwerkende β2-agonist die binnen minuten de luchtwegen verwijdt; gebruikt bij astma- en COPD-aanvallen.","definition":"<p><strong>Salbutamol</strong> ontspant de gladde spier van de bronchi via β2-receptoren en cAMP. Het werkt binnen enkele minuten en ongeveer 4–6 uur. Het wordt via een dosisaerosol met voorzetkamer of als verneveling gegeven. Bijwerkingen: tremor, tachycardie en een daling van het kalium (het wordt daarom ook gebruikt bij hyperkaliëmie).</p>","image_url":"","wiki_title":"Salbutamol","match":"een beta-2-sympaticomimeticum","option_only":true},"kortwerkend beta-2-ympaticomimeticum":{"title":"Salbutamol","short":"Salbutamol is een kortwerkende β2-agonist die binnen minuten de luchtwegen verwijdt; gebruikt bij astma- en COPD-aanvallen.","definition":"<p><strong>Salbutamol</strong> ontspant de gladde spier van de bronchi via β2-receptoren en cAMP. Het werkt binnen enkele minuten en ongeveer 4–6 uur. Het wordt via een dosisaerosol met voorzetkamer of als verneveling gegeven. Bijwerkingen: tremor, tachycardie en een daling van het kalium (het wordt daarom ook gebruikt bij hyperkaliëmie).</p>","image_url":"","wiki_title":"Salbutamol","match":"kortwerkend beta-2-ympaticomimeticum","option_only":true},"mycoplasmapneumonie":{"title":"Mycoplasma pneumoniae","short":"Mycoplasma pneumoniae is een bacterie zonder celwand die bij jongeren een ‘atypische’ pneumonie veroorzaakt.","definition":"<p><strong><em>Mycoplasma pneumoniae</em></strong> heeft geen peptidoglycaanwand en is daardoor ongevoelig voor bètalactamantibiotica en niet zichtbaar met een gramkleuring. Het veroorzaakt vooral bij schoolkinderen en jongvolwassenen een geleidelijk beginnende luchtweginfectie met droge hoest. Er kunnen koude agglutininen (hemolyse) en extrapulmonale verschijnselen optreden. Behandeling met macroliden of doxycycline.</p>","image_url":"","wiki_title":"Mycoplasma pneumoniae","match":"mycoplasmapneumonie","option_only":true},"psittacose (chlamydia psittaci)":{"title":"Psittacose","short":"Psittacose is een longontsteking door Chlamydia psittaci, opgelopen via (stof van) besmette vogels.","definition":"<p>Bij <strong>psittacose</strong> zijn er hoge koorts, hoofdpijn, droge hoest en spierpijn, soms met een relatief trage pols. Contact met vogels (papegaaien, duiven) is de belangrijkste aanwijzing. Behandeling met doxycycline.</p>","image_url":"","wiki_title":"Psittacosis","match":"psittacose (chlamydia psittaci)","option_only":true},"vasculaire claudicatio intermittens":{"title":"Claudicatio intermittens","short":"Claudicatio intermittens is pijn in de kuit of bil bij lopen die bij stilstaan verdwijnt, door perifeer arterieel vaatlijden.","definition":"<p>Bij <strong>claudicatio</strong> zijn de beenarteriën vernauwd door atherosclerose. De enkel-armindex is verlaagd (&lt;0,9). Behandeling: stoppen met roken, gesuperviseerde looptraining, een plaatjesremmer en statine; bij ernstige klachten of kritieke ischemie (rustpijn, wonden) revascularisatie.</p>","image_url":"","wiki_title":"Intermittent claudication","match":"vasculaire claudicatio intermittens","option_only":true},"een diffusiestoornis":{"title":"Diffusiestoornis","short":"Bij een diffusiestoornis gaat zuurstof minder goed van de alveoli naar het bloed, door verdikking van de membraan of verlies van oppervlak.","definition":"<p>Een <strong>diffusiestoornis</strong> wordt gemeten met de DLCO (koolmonoxide-diffusiecapaciteit). Ze komt voor bij interstitiële longziekten (verdikte alveolaire wand), emfyseem (verlies van oppervlak), pulmonale hypertensie en anemie. De hypoxemie wordt vaak pas duidelijk bij inspanning, omdat het bloed dan korter in de capillair verblijft.</p>","image_url":"","wiki_title":"Diffusing capacity for carbon monoxide","match":"een diffusiestoornis","option_only":true},"sterk verhoogd c-reactief proteïne (crp)":{"title":"CRP","short":"C-reactief proteïne; ontstekingseiwit in het bloed dat helpt de kans op een gecompliceerde infectie in te schatten.","definition":"<p>Het CRP stijgt bij ontsteking of infectie; in de huisartsenpraktijk stuurt het het antibioticabeleid bij luchtweginfecties.</p>","image_url":"","wiki_title":"C-reactive_protein","match":"sterk verhoogd c-reactief proteïne (crp)","option_only":true},"ct-angio":{"title":"CT-angiografie thorax","short":"CT-scan met contrast van de longvaten om een longembolie aan te tonen of uit te sluiten.","definition":"<p>Bij CTA (CT-angio) thorax worden de pulmonale arteriën met contrast in beeld gebracht; het is de gouden standaard voor het aantonen van een longembolie.</p>","image_url":"","wiki_title":"","match":"ct-angio","option_only":true},"judo-techniek":{"title":"Judo-techniek","short":"Gesprekstechniek uit de motiverende gespreksvoering voor het omgaan met weerstand.","definition":"<p>De <b>judo-techniek</b> komt uit de motiverende gespreksvoering. Net als bij judo gebruik je de ‘kracht’ van de ander in plaats van ertegenin te duwen: je erkent het standpunt van de patiënt en gaat niet in discussie, zodat de patiënt zelf ruimte krijgt om andere afwegingen te maken.</p>","image_url":"","wiki_title":"","match":"judo-techniek","option_only":true},"ct angio":{"title":"CT-angiografie thorax","short":"CT-scan met contrast van de longvaten om een longembolie aan te tonen of uit te sluiten.","definition":"<p>Bij CTA (CT-angio) thorax worden de pulmonale arteriën met contrast in beeld gebracht; het is de gouden standaard voor het aantonen van een longembolie.</p>","image_url":"","wiki_title":"","match":"ct angio","option_only":true},"nt-pro bnp":{"title":"BNP (brain natriuretic peptide)","short":"BNP is een hormoon uit de hartkamers dat vrijkomt bij rek van de wand; een verhoogde waarde past bij hartfalen.","definition":"<p><strong>BNP</strong> en het inactieve NT-proBNP worden afgegeven door ventrikelcellen bij volume- of drukbelasting. BNP bevordert natriurese en vaatverwijding en remt het RAAS. Een normale waarde maakt hartfalen bij een kortademige patiënt onwaarschijnlijk. Ook nierfalen, hoge leeftijd, longembolie en boezemfibrilleren verhogen de waarde.</p>","image_url":"","wiki_title":"Brain natriuretic peptide","match":"nt-pro bnp","option_only":true},"door werk verergerd astma":{"title":"Beroepsastma","short":"Beroepsastma is astma dat door stoffen op het werk ontstaat, zoals meelstof bij bakkers of isocyanaten bij spuiters.","definition":"<p>Typisch voor <strong>beroepsastma</strong> zijn klachten die verbeteren in het weekend en de vakanties. Vroeg stoppen met blootstelling geeft de beste kans op herstel. Het is een beroepsziekte die moet worden gemeld.</p>","image_url":"","wiki_title":"Occupational asthma","match":"door werk verergerd astma","option_only":true},"(nt-pro-)bnp":{"title":"BNP (brain natriuretic peptide)","short":"BNP is een hormoon uit de hartkamers dat vrijkomt bij rek van de wand; een verhoogde waarde past bij hartfalen.","definition":"<p><strong>BNP</strong> en het inactieve NT-proBNP worden afgegeven door ventrikelcellen bij volume- of drukbelasting. BNP bevordert natriurese en vaatverwijding en remt het RAAS. Een normale waarde maakt hartfalen bij een kortademige patiënt onwaarschijnlijk. Ook nierfalen, hoge leeftijd, longembolie en boezemfibrilleren verhogen de waarde.</p>","image_url":"","wiki_title":"Brain natriuretic peptide","match":"(nt-pro-)bnp","option_only":true},"d-dimeer":{"title":"D-dimeer","short":"Afbraakproduct van fibrine; een normale waarde sluit bij lage verdenking een trombose/longembolie vrijwel uit.","definition":"<p>D-dimeer is een fibrinolyse-afbraakproduct. Een normale waarde bij lage klinische verdenking sluit een longembolie uit; een verhoogde waarde is aspecifiek en vereist beeldvorming.</p>","image_url":"","wiki_title":"","match":"d-dimeer","option_only":true},"surmenage":{"title":"Surmenage","short":"Overbelasting door aanhoudende stress; nauw verwant aan overspanning en aanpassingsstoornis.","definition":"<p><b>Surmenage</b> is een toestand van overbelasting door langdurige of overmatige (psychische) inspanning en stress, waarbij lichamelijke en psychische klachten optreden. De term overlapt met overspanning en aanpassingsstoornis.</p>","image_url":"","wiki_title":"","match":"surmenage","option_only":true},"saturatie":{"title":"Zuurstofsaturatie","short":"Percentage hemoglobine dat met zuurstof is verzadigd; maat voor de oxygenatie.","definition":"<p>De (perifere) zuurstofsaturatie (SpO2) geeft aan welk deel van het hemoglobine met O2 is verzadigd. Bij CO-vergiftiging kan de SpO2 vals-normaal zijn.</p>","image_url":"","wiki_title":"Oxygen saturation (medicine)","match":"saturatie","option_only":true},"hemoptoë":{"title":"Hemoptoë","short":"Het ophoesten van bloed uit de lagere luchtwegen; kan een symptoom zijn van een pulmonaal-renaal syndroom.","definition":"<p><b>Hemoptoë</b> is het ophoesten van bloed afkomstig uit de longen of lagere luchtwegen. In combinatie met nierinsufficiëntie kan het wijzen op een pulmonaal-renaal syndroom (anti-GBM-ziekte of ANCA-vasculitis).</p>","image_url":"","wiki_title":"Hemoptysis","match":"hemoptoë","option_only":true},"allergisch astma":{"title":"Astmafenotypen","short":"Astma wordt ingedeeld in fenotypen, zoals allergisch astma (met sensibilisatie, vaak beginnend in de jeugd), eosinofiel astma en niet-allergisch astma.","definition":"<p>Bij <strong>allergisch astma</strong> zijn er IgE-antistoffen tegen bijv. huisstofmijt, pollen of dierhaar, en een type 2-ontsteking. Bronchiale hyperreactiviteit (overgevoeligheid van de luchtwegen) is kenmerkend voor alle vormen van astma.</p>","image_url":"","wiki_title":"Asthma","match":"allergisch astma|hyperreactief astma|eosinofiel astma|niet-allergisch astma","option_only":true},"levofloxacine":{"title":"Fluorochinolonen","short":"Levofloxacine en ciprofloxacine zijn fluorochinolonen, die bacterieel DNA-gyrase en topo-isomerase IV remmen.","definition":"<p><strong>Fluorochinolonen</strong> werken breed, ook bij gramnegatieve bacteriën en (levofloxacine, moxifloxacine) bij luchtwegpathogenen. Ze hebben ernstige bijwerkingen: peesrupturen, QT-verlenging, aneurysma's en neuropathie, en worden daarom terughoudend gebruikt.</p>","image_url":"","wiki_title":"Fluoroquinolone","match":"levofloxacine|ciprofloxacine|moxifloxacine|fluorochinolonen","option_only":true},"d-dimeer bepalen":{"title":"D-dimeer","short":"D-dimeer is een afbraakproduct van fibrine; een normale waarde maakt trombose of longembolie onwaarschijnlijk bij een laag klinisch risico.","definition":"<p><strong>D-dimeer</strong> is gevoelig maar niet specifiek: het is ook verhoogd na operaties, bij infecties, kanker, zwangerschap en ouderdom. Daarom wordt het alleen gebruikt in combinatie met een beslisregel (Wells, YEARS).</p>","image_url":"","wiki_title":"D-dimer","match":"d-dimeer bepalen|d-dimeer|d-dimeren","option_only":true},"werkgerelateerd astma":{"title":"Beroepsastma","short":"Beroepsastma is astma dat door stoffen op het werk ontstaat, zoals meelstof bij bakkers of isocyanaten bij spuiters.","definition":"<p>Typisch voor <strong>beroepsastma</strong> zijn klachten die verbeteren in het weekend en de vakanties. Vroeg stoppen met blootstelling geeft de beste kans op herstel. Het is een beroepsziekte die moet worden gemeld.</p>","image_url":"","wiki_title":"Occupational asthma","match":"werkgerelateerd astma","option_only":true}};
